def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue

            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and not seen[ny][nx]):
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            boxes = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in boxes:
                    boxes[color] = [y, y, x, x]
                else:
                    box = boxes[color]
                    box[0] = min(box[0], y)
                    box[1] = max(box[1], y)
                    box[2] = min(box[2], x)
                    box[3] = max(box[3], x)

            order = sorted(
                boxes,
                key=lambda color: (boxes[color][1] - boxes[color][0] + 1) *
                                  (boxes[color][3] - boxes[color][2] + 1),
                reverse=True
            )
            remap = {color: order[-1 - i] for i, color in enumerate(order)}
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]

    return out

