def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate a uniform divider that leaves equal-sized panels.
    split = None
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            split = ("row", r)
            break
    if split is None:
        for c in range(1, w - 1):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w - c - 1:
                split = ("col", c)
                break

    direction, k = split
    if direction == "row":
        a = [row[:] for row in grid[:k]]
        b = [row[:] for row in grid[k + 1:]]
    else:
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    def marker(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        background = max(counts, key=counts.get)
        return min((value for value in counts if value != background),
                   key=lambda value: counts[value])

    ma, mb = marker(a), marker(b)
    out = [[ma for _ in row] for row in a]
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] == ma and b[r][c] == mb:
                out[r][c] = 3
    return out

