from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    def dominant(line):
        color, n = Counter(line).most_common(1)[0]
        return color, n / len(line)

    row_info = [dominant(row) for row in grid]
    col_info = [dominant([grid[r][c] for r in range(h)]) for c in range(w)]

    def progressions(info, color, length):
        eligible = {i for i, (c, frac) in enumerate(info)
                    if c == color and frac >= 0.65}
        result = []
        for step in range(2, length):
            for start in sorted(eligible):
                seq = []
                i = start
                while i in eligible:
                    seq.append(i)
                    i += step
                if len(seq) >= 3:
                    result.append(seq)
        # Keep distinct progressions.
        return list({tuple(x) for x in result})

    best = None
    for color in range(10):
        rsets = progressions(row_info, color, h)
        csets = progressions(col_info, color, w)
        for rows in rsets:
            for cols in csets:
                deviations = sum(grid[r][c] != color for r in rows for c in cols)
                # Prefer a real marked lattice, then longer, regular line sequences.
                score = (deviations, len(rows) * len(cols),
                         len(rows) + len(cols))
                if best is None or score > best[0]:
                    best = (score, color, list(rows), list(cols))

    if best is None:
        return grid

    _, line_color, rows, cols = best
    fill_counts = Counter(v for row in grid for v in row if v != line_color)
    fill = fill_counts.most_common(1)[0][0] if fill_counts else line_color

    out = []
    for i in range(len(rows) - 1):
        out_row = []
        for j in range(len(cols) - 1):
            corners = [grid[rows[i]][cols[j]],
                       grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]],
                       grid[rows[i + 1]][cols[j + 1]]]
            v = corners[0]
            out_row.append(v if v != line_color and all(x == v for x in corners) else fill)
        out.append(out_row)

    marked = [(r, c) for r, row in enumerate(out) for c, v in enumerate(row)
              if v != fill]
    if not marked:
        return [[fill]]
    r0, r1 = min(r for r, _ in marked), max(r for r, _ in marked)
    c0, c1 = min(c for _, c in marked), max(c for _, c in marked)
    return [row[c0:c1 + 1] for row in out[r0:r1 + 1]]

