def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The horizontal bars have several colored cells; the vertical markers
    # are below the last such row.
    bar_rows = [r for r in range(h) if sum(v != 0 for v in grid[r]) >= 2]
    if not bar_rows:
        return out
    last_bar = max(bar_rows)

    for c in range(w):
        marker_cells = [(r, grid[r][c]) for r in range(last_bar + 1, h)
                        if grid[r][c] != 0]
        if not marker_cells:
            continue
        marker_color = marker_cells[-1][1]

        events = []
        for r in bar_rows:
            if grid[r][c] != 0:
                continue
            left = next((grid[r][j] for j in range(c - 1, -1, -1)
                         if grid[r][j] != 0), 0)
            right = next((grid[r][j] for j in range(c + 1, w)
                          if grid[r][j] != 0), 0)
            if left and left == right:
                events.append((r, left))

        if not events:
            for r in range(h):
                out[r][c] = marker_color
            continue

        # Above the first bar gap, extend its color. Between gaps, use the
        # color of the next gap; below the last gap, extend the marker color.
        first_r, first_color = events[0]
        for r in range(first_r + 1):
            out[r][c] = first_color
        for (r1, _), (r2, color) in zip(events, events[1:]):
            for r in range(r1 + 1, r2 + 1):
                out[r][c] = color
        last_r = events[-1][0]
        for r in range(last_r + 1, h):
            out[r][c] = marker_color

    return out

