def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Mark background zeroes connected to the edge using 4-way connectivity.
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not outside[nr][nc]):
                outside[nr][nc] = True
                q.append((nr, nc))

    inside = [[grid[r][c] == 0 and not outside[r][c]
               for c in range(w)] for r in range(h)]

    # Find 4-connected components of the outline. A component bordering an
    # enclosed zero region is a closed outline to be accented.
    seen = [[False] * w for _ in range(h)]
    eligible = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen[r][c]:
                continue
            comp = []
            q = deque([(r, c)])
            seen[r][c] = True
            touches_inside = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if inside[ny][nx]:
                            touches_inside = True
                        if grid[ny][nx] == 1 and not seen[ny][nx]:
                            seen[ny][nx] = True
                            q.append((ny, nx))
            if touches_inside:
                eligible.update(comp)

    # Add an inner accent (3) and an outer accent (2), both one cell thick.
    for r, c in eligible:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                    if inside[nr][nc]:
                        out[nr][nc] = 3
                    else:
                        out[nr][nc] = 2
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1

    # The boundary color appears on two opposite edges.
    boundary = None
    for v in counts:
        if v == bg:
            continue
        if (any(grid[0][c] == v for c in range(w)) and any(grid[h-1][c] == v for c in range(w))) or \
           (any(grid[r][0] == v for r in range(h)) and any(grid[r][w-1] == v for r in range(h))):
            boundary = v
            break
    if boundary is None:
        return [row[:] for row in grid]

    markers = [(r, c, v) for r in range(h) for c in range(w)
               if grid[r][c] not in (bg, boundary)]
    if not markers:
        return [row[:] for row in grid]
    r, c, color = markers[0]
    out = [row[:] for row in grid]

    # Find the two boundary runs and the marker's corresponding run.
    if any(grid[0][x] == boundary for x in range(w)) and any(grid[h-1][x] == boundary for x in range(w)):
        def run(row):
            xs = [x for x in range(w) if grid[row][x] == boundary]
            return min(xs), max(xs)
        top, bottom = run(0), run(h-1)
        if top[0] <= c <= top[1]:
            near, far, nearpos, farpos = 0, h-1, top, bottom
            toward = -1
        else:
            near, far, nearpos, farpos = h-1, 0, bottom, top
            toward = 1
        # Marker rays toward its aligned boundary.
        for rr in range(r + toward, near + toward, toward):
            out[rr][c] = color
        out[r][c] = 4
        mapped = c + (farpos[0] - nearpos[0])
        mapped = max(0, min(w-1, mapped))
        step = 1 if far == 0 else -1
        for rr in range(far + step, h if step == 1 else -1, step):
            if out[rr][mapped] != boundary:
                out[rr][mapped] = color
    else:
        def run(col):
            ys = [y for y in range(h) if grid[y][col] == boundary]
            return min(ys), max(ys)
        left, right = run(0), run(w-1)
        if left[0] <= r <= left[1]:
            near, far, nearpos, farpos = 0, w-1, left, right
            toward = -1
        else:
            near, far, nearpos, farpos = w-1, 0, right, left
            toward = 1
        for cc in range(c + toward, near + toward, toward):
            out[r][cc] = color
        out[r][c] = 4
        mapped = r + (farpos[0] - nearpos[0])
        mapped = max(0, min(h-1, mapped))
        step = 1 if far == 0 else -1
        for cc in range(far + step, w if step == 1 else -1, step):
            if out[mapped][cc] != boundary:
                out[mapped][cc] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    squares = []

    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color
                             for i in range(r, r + 3)
                             for j in range(c, c + 3)):
                squares.append((color, r + 1, c + 1))

    out = [row[:] for row in grid]
    lines = {}

    for color, r, c in squares:
        for j in range(w):
            lines.setdefault((r, j), set()).add(color)
        for i in range(h):
