def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def intervals(n, seps):
        result = []
        start = 0
        for p in seps:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < n:
            result.append((start, n))
        return result

    rs = intervals(h, sep_rows)
    cs = intervals(w, sep_cols)

    panels = [(r0, r1, c0, c1) for r0, r1 in rs for c0, c1 in cs]
    source = max(
        panels,
        key=lambda p: sum(grid[r][c] != bg
                          for r in range(p[0], p[1])
                          for c in range(p[2], p[3]))
    )
    r0, r1, c0, c1 = source
    pattern = [row[c0:c1] for row in grid[r0:r1]]

    out = [row[:] for row in grid]
    for a, b, x, y in panels:
        for i, r in enumerate(range(a, b)):
            for j, c in enumerate(range(x, y)):
                out[r][c] = pattern[i][j]
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Connect diagonal pairs of 1s.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2 - r1) == abs(c2 - c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                r, c = r1 + dr, c1 + dc
                while (r, c) != (r2, c2):
                    if grid[r][c] == 0 or grid[r][c] not in (1, 6):
                        out[r][c] = 1
                    r += dr
                    c += dc

    # Extend each 6 along its NW-SE diagonal, stopping only at grid edges.
    for r, c in sixes:
        for dr in (-1, 1):
            rr, cc = r + dr, c + dr
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] not in (1, 6):
                    out[rr][cc] = 6
                rr += dr
                cc += dr

    return out

def transform(grid):
    from collections import Counter, defaultdict

    h, w = len(grid), len(grid[0])
    counts_by_period = {}
    for p in range(2, 11):
        counts = defaultdict(Counter)
        for r in range(3, h):
            for c in range(3, w):
                v = grid[r][c]
                if v != 0:
                    counts[(r + c) % p][v] += 1
        mapping = {k: ctr.most_common(1)[0][0] for k, ctr in counts.items()}
        agreement = sum(ctr[mapping[k]] for k, ctr in counts.items())
        counts_by_period[p] = (agreement - 0.2 * p, mapping)

    period = max(counts_by_period, key=lambda p: counts_by_period[p][0])
    mapping = counts_by_period[period][1]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = mapping[(r + c) % period]
    return out

